---
template: envsubst
title: Env
---
overlay ${AOS_OVERLAY_NAME} root ${AOS_OVERLAY_ROOT} scope ${AOS_OVERLAY_SCOPE}
project ${AOS_PROJECT_ROOT} state ${AOS_OVERLAY_STATE}
role ${AOS_CALLER_ROLE} profile ${AOS_CALLER_PROFILE}
user ${AOS_ENV_USER} home ${AOS_ENV_HOME} off ${AOS_ENV_SHELL_X}
topic ${AOS_ARG_topic} n ${AOS_ARG_count} flag ${AOS_ARG_deep} list ${AOS_ARG_items}
depth ${depth} token ${token} plain ${HOME} $${AOS_OVERLAY_NAME} {{overlay.name}}

---
template: mustache
---
# {{overlay.name}}
{{#caller.role}}
Role: {{caller.role}}
{{/caller.role}}
{{^caller.profile}}
No profile
{{/caller.profile}}
  {{! a comment }}
{{#context.items}}
- {{.}}
{{/context.items}}
{{#context.people}}{{name}} is {{age}} at {{overlay.name}}
{{/context.people}}env {{env.USER}} missing [{{env.NOPE}}] depth {{options.depth}} strict {{options.strict}}
raw {{{context.html}}} {{&context.html}} {{context.html}}
shell ${HOME} ${AOS_OVERLAY_NAME}

